  'awsLogs.anomaly.method': 'Comparado con los 7 días anteriores de este grupo, hasta las {time} (último evento sincronizado). Estadística sobre agregados locales: sin IA y sin llamadas a AWS.',
  'awsLogs.anomaly.viewWindow': 'Ver tramo',
  'awsLogs.anomaly.status_not_synced': 'Las anomalías aparecen después de la primera sincronización de este grupo.',
  'awsLogs.anomaly.status_insufficient_history': 'Todavía no hay historia suficiente: las anomalías necesitan al menos 6 horas de logs sincronizados para comparar.',
